head.script:
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('gridView1_body_tbody').querySelectorAll('tr')[0].classList.contains('w2grid_lastRow');
}		
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column7_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_customFilter_list').querySelectorAll('div')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_customFilter_list').querySelectorAll('div')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column7_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_1').text() == 'a'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    dst_scrnItmTypCd.setData(['a', '1', 'b', '2']);
    dataList1.setData([1, 2, 3, 4, 2, 6, 7, 1, 9]);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 01-Mar-2018
}
